insert into public.skills (slug,name,class_affinity,category,difficulty,description,progression_group,unlock_level,xp_reward,primary_attribute,equipment,safety_notes,mastery_metric,mastery_target,mastery_unit,mastery_notes,sort_order,is_active,updated_at)
select slug,name,class_affinity,category,difficulty,description,progression_group,unlock_level,xp_reward,primary_attribute,equipment,safety_notes,mastery_metric,mastery_target,mastery_unit,mastery_notes,sort_order,true,now() from data
on conflict (slug) do update set name=excluded.name,class_affinity=excluded.class_affinity,category=excluded.category,difficulty=excluded.difficulty,description=excluded.description,progression_group=excluded.progression_group,unlock_level=excluded.unlock_level,xp_reward=excluded.xp_reward,primary_attribute=excluded.primary_attribute,equipment=excluded.equipment,safety_notes=excluded.safety_notes,mastery_metric=excluded.mastery_metric,mastery_target=excluded.mastery_target,mastery_unit=excluded.mastery_unit,mastery_notes=excluded.mastery_notes,sort_order=excluded.sort_order,is_active=true,updated_at=now();
